INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 7, 'theory', 'Quiz: the preprocessor, macros, and header files');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 0, 'What is the include guard (#ifndef X_H / #define X_H / … / #endif) in a header for?', '["So the header compiles faster on any platform", "So that including the header again does not define the types a second time", "To forbid including the header from other files", "To encrypt the contents of the header"]', 1, 'A header is often included several times along a chain of includes. The guard skips the text on a repeat, so structures are not defined twice.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 1, 'What does SQ(a + 1) expand to with #define SQ(x) x * x?', '["(a + 1) * (a + 1)", "a * a + 1", "An error: expressions can''t be passed to a macro", "a + 1 * a + 1"]', 3, 'The preprocessor substitutes text: you get a + 1 * a + 1, where multiplication is done before addition. That is why macro parameters are put in parentheses in the body.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 2, 'Why is a multi-statement macro wrapped in do { … } while (0)?', '["So the macro behaves as a single statement, including in an if without braces", "So the macro runs several times", "So it runs faster than an ordinary function", "So the compiler does not optimize it"]', 0, 'Without the wrapper, in an if branch without braces only the first statement falls under the condition. do-while(0) runs exactly once, and the semicolon after the call turns it into an ordinary statement.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 3, 'What does S(N) give with #define N 5, #define S1(x) #x, and #define S(x) S1(x)?', '["The number 5", "The string \"N\" — same as S1(N)", "The string \"5\": the argument is expanded before being passed to the inner macro", "A compilation error"]', 2, 'The # operator is applied to the argument without expansion: S1(N) gives "N". In the outer macro S the argument is expanded to 5 first, and S1 receives 5 already — the result is "5".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 4, 'What is the best replacement for a MAX(a, b) macro whose argument is evaluated twice?', '["One more pair of parentheses around the parameters", "The #undef directive", "A macro with the double hash", "A static inline function — the argument is evaluated once, and there are types"]', 3, 'A function evaluates its arguments once, has type checking, and the compiler can still inline the body. Parentheses do not remove double evaluation.');
